#import "TFAIISHEnvironmentUI.h"
#import "TFAIISHRuntime.h"
#import "TFAIISHEnvironment.h"
#import "../UI/TFAIUIHelpers.h"
#import "../Agent/TFAIAgentContext.h"
@interface DylixEnvironmentPage : UITableViewController
@property NSString *session,*projectRoot;
@property NSDictionary *inventory;
@end
@implementation DylixEnvironmentPage
- (void)viewDidLoad{[super viewDidLoad];self.title=@"Linux 环境";self.tableView.accessibilityIdentifier=@"linux-environment-table";self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=66;self.navigationItem.rightBarButtonItem=AIBar(@"arrow.clockwise",@"刷新环境",self,@selector(refresh));[self refresh];}
- (void)refresh{__weak typeof(self) weak=self;[TFAIISHRuntime.shared environmentInventory:^(NSDictionary *value){weak.inventory=value;[weak.tableView reloadData];}];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)table{return 4;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?3:s==1?1:s==2?[self.inventory[@"sessions"] count]:[self.inventory[@"snapshots"] count];}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return @[@"本机环境",@"维护安排",@"共享环境与保留的旧环境",@"可恢复快照"][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{if(s==1)return @"快照、恢复与重建在下次重新启动 App 后、Linux 内核启动前执行；当前进程不会删除或替换正在使用的文件系统。重建/恢复前完整备份 fakefs 数据与元数据，项目文件和聊天不变。";if(s==2)return @"所有终端和 AI 共用持久环境。旧环境保留，可重启切换找回工具；原共享环境也会保留。删除聊天不会删除工具；重建、删除或更换 Linux 版本会影响环境中的工具。";return nil;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{
 if(i.section==0){if(i.row==0)return AICell(self.inventory[@"version"]?:@"Alpine Linux",[self.inventory[@"available"] boolValue]?([self.inventory[@"booted"] boolValue]?@"运行库已启动":@"运行库可用 · 尚未启动"):@"此构建没有可用运行库",@"terminal");if(i.row==1)return AICell(@"Linux 文件与快照占用",[NSByteCountFormatter stringFromByteCount:[self.inventory[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile],@"internaldrive");return AICell(@"内置 rootfs SHA-256",self.inventory[@"archiveSHA256"]?:@"正在校验",@"checkmark.shield");}
 if(i.section==1){NSDictionary *p=self.inventory[@"pending"];UITableViewCell *c=AICell(p.count?@"已安排维护 · 点击取消":@"没有待执行维护",p.count?[NSString stringWithFormat:@"%@ · %@…\n重启后首次打开终端执行",p[@"operation"],[p[@"sessionKey"] substringToIndex:MIN(12,[p[@"sessionKey"] length])]]:@"选择环境可备份、恢复或找回旧工具",@"clock");c.accessibilityIdentifier=@"linux-maintenance-pending";return c;}
 NSDictionary *row=self.inventory[i.section==2?@"sessions":@"snapshots"][i.row];NSString *key=row[i.section==2?@"key":@"sessionKey"],*current=TFAIISHEnvironment.sharedKey;UITableViewCell *cell=AICell([NSString stringWithFormat:@"%@%@…",[key isEqual:current]?@"共享工具环境 · ":@"",[key substringToIndex:MIN(12,key.length)]],[NSString stringWithFormat:@"%@%@",[NSByteCountFormatter stringFromByteCount:[row[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile],i.section==3?[@" · " stringByAppendingString:[row[@"createdAt"] description]]:[@" · " stringByAppendingString:row[@"version"]?:@"Alpine"]],i.section==2?@"externaldrive":@"archivebox");cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;
}
- (void)confirm:(NSString *)operation key:(NSString *)key snapshot:(NSString *)snapshot{
 NSString *title=[@{@"backup":@"安排完整快照？",@"reset":@"安排备份并重建？",@"restore":@"安排恢复此快照？",@"delete":@"删除这个 Linux 环境？",@"activate":@"使用这份旧环境的工具？"} objectForKey:operation];UIAlertController *a=[UIAlertController alertControllerWithTitle:title message:[operation isEqual:@"activate"]?@"重启后将这份旧环境切换为所有终端共用的环境。当前共享环境会保留在原旧环境位置，不合并或删除工具。": [operation isEqual:@"delete"]?@"下次重启后、终端启动前删除。此操作不再创建快照，将丢失该环境中的文件和已安装工具；项目源码与聊天记录保留。请先导出需要的文件。":@"下次重启 App 后、打开终端时执行。所选 Linux 环境会先完整备份；项目源码、消息和人设不会清除。请先保存终端中的工作。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"确认安排" style:[operation isEqual:@"backup"]?UIAlertActionStyleDefault:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[TFAIISHRuntime.shared scheduleMaintenance:operation sessionKey:key snapshot:snapshot completion:^(NSError *e){if(e)AIAlert(self,@"未安排维护",e.localizedDescription);else AIAlert(self,@"已安排",@"请重新启动 App，再打开终端。不会自动终止当前任务。");[self refresh];}];}]];[self presentViewController:a animated:YES completion:nil];
}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)i{[table deselectRowAtIndexPath:i animated:YES];if(i.section==0)return;if(i.section==1){if(![self.inventory[@"pending"] count])return;UIAlertController *a=[UIAlertController alertControllerWithTitle:@"取消待执行维护？" message:@"只取消安排，现有文件与快照不变。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"返回" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"取消维护" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[TFAIISHRuntime.shared cancelMaintenance:^(NSError *e){if(e)AIAlert(self,@"取消失败",e.localizedDescription);[self refresh];}];}]];[self presentViewController:a animated:YES completion:nil];return;}
 NSDictionary *row=self.inventory[i.section==2?@"sessions":@"snapshots"][i.row];if(i.section==3){UIAlertController *actions=[UIAlertController alertControllerWithTitle:@"环境快照" message:@"恢复前会另存当前环境；删除只影响此快照。" preferredStyle:UIAlertControllerStyleActionSheet];[actions addAction:[UIAlertAction actionWithTitle:@"恢复此快照" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){[self confirm:@"restore" key:row[@"sessionKey"] snapshot:row[@"id"]];}]];[actions addAction:[UIAlertAction actionWithTitle:@"删除此快照" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *a){UIAlertController *confirm=[UIAlertController alertControllerWithTitle:@"永久删除此快照？" message:@"删除后无法用它恢复环境。当前会话文件和其他快照不变。" preferredStyle:UIAlertControllerStyleAlert];[confirm addAction:[UIAlertAction actionWithTitle:@"保留" style:UIAlertActionStyleCancel handler:nil]];[confirm addAction:[UIAlertAction actionWithTitle:@"删除快照" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[TFAIISHRuntime.shared deleteEnvironmentSnapshot:row[@"id"] completion:^(NSError *e){if(e)AIAlert(self,@"快照未删除",e.localizedDescription);[self refresh];}];}]];[self presentViewController:confirm animated:YES completion:nil];}]];[actions addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];actions.popoverPresentationController.sourceView=[table cellForRowAtIndexPath:i];[self presentViewController:actions animated:YES completion:nil];return;}
 UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Linux 环境维护" message:[row[@"shared"] boolValue]?@"这是全部终端和 AI 共用的环境，删除或重建会影响全部工具。":@"这是保留的旧环境，可切换回来找回工具。" preferredStyle:UIAlertControllerStyleActionSheet];if(![row[@"shared"] boolValue])[a addAction:[UIAlertAction actionWithTitle:@"切换为共享工具环境（重启后）" style:UIAlertActionStyleDefault handler:^(id action){[self confirm:@"activate" key:row[@"key"] snapshot:nil];}]];for(NSString *op in @[@"backup",@"reset",@"delete"])[a addAction:[UIAlertAction actionWithTitle:[op isEqual:@"backup"]?@"备份完整环境":[op isEqual:@"delete"]?@"删除环境以释放空间（重启后）":@"先备份，再重建环境" style:[op isEqual:@"backup"]?UIAlertActionStyleDefault:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[self confirm:op key:row[@"key"] snapshot:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[table cellForRowAtIndexPath:i];[self presentViewController:a animated:YES completion:nil];
}
@end
UIViewController *TFAIISHEnvironmentController(NSString *session,NSString *root){DylixEnvironmentPage *page=[[DylixEnvironmentPage alloc]initWithStyle:UITableViewStyleInsetGrouped];page.session=session;page.projectRoot=root;return page;}
